-- Entries for the launch trackers, with their fields from seed/trackers.json. The data
-- goes in as the browser holds it and must be stored exactly as cleanEntry tidies it.
do $world$
begin
  perform tests.make_world();
  insert into public.trackers (slug, name, color, cadence, fields) values
    ('parity-singapore-math', 'Parity singapore-math', 'ink-blue', '{"type": "plan"}', '[{"key":"checklist","type":"checklist","label":"Today''s checklist","required":true,"options":[{"key":"attempted","label":"Attempted the assigned problems"},{"key":"checked","label":"Checked answers and corrected mistakes"},{"key":"explained","label":"Explained one key idea"},{"key":"retry_planned","label":"Picked problems to retry (or none needed)"}]},{"key":"outcomes","type":"tally_group","label":"How each problem went","required":false,"help":"Tap once per problem or lettered part. Checking a solution after solving it yourself still counts as I.","options":[{"key":"I","label":"Solved on my own","shortcut":"i"},{"key":"H","label":"Solved after a hint","shortcut":"h"},{"key":"S","label":"Needed the solution","shortcut":"s"},{"key":"U","label":"Still unsolved","shortcut":"u"}],"showIf":{"plan.reading_only":false}},{"key":"minutes","type":"duration","label":"Minutes","required":true},{"key":"key_idea","type":"short_text","label":"Key idea or error to watch","required":false,"help":"Specific beats general: \"total distance ÷ total time, not the average of the speeds\"."},{"key":"did","type":"long_text","label":"What I did","required":true,"default":"plan.assignment"},{"key":"struggled","type":"long_text","label":"What I struggled with","required":true},{"key":"reflection","type":"long_text","label":"Reflection","required":false,"rotatingPrompts":["What was the key observation?","Why does that step work?","How could you check the answer?","What change would make this method stop working?"],"rotateBy":"plan.session"},{"key":"notebook","type":"photo","label":"Notebook photo","required":false}]'::jsonb),
    ('parity-violin', 'Parity violin', 'ink-blue', '{"type": "daily"}', '[{"key":"practiced","type":"yes_no","label":"Did you practice today?","required":true},{"key":"focus","type":"short_text","label":"One specific thing you focused on","required":true,"placeholder":"clean shift to 3rd position in bar 12","showIf":{"practiced":true}}]'::jsonb);
  insert into tests.world select slug, id from public.trackers where slug like 'parity-%';
  perform public.assign_tracker(tests.id('student'), 'parity-singapore-math', date '2026-01-01');
  perform public.assign_tracker(tests.id('student'), 'parity-violin', date '2026-01-01');
  with p as (insert into public.plan_items (assignment_id, date, title, details) values (tests.assignment('student', 'parity-singapore-math'), date '2026-01-01', 'parity-plan-1', '{"session":6,"week":2,"topic":"Solve by Assuming","assignment":"Practice pp. 31-32","page_start":31,"page_end":32,"kind":"practice","reading_only":false,"pdf_offset":2}'::jsonb) returning id)
  insert into tests.world select 'parity-plan-1', id from p;
  with p as (insert into public.plan_items (assignment_id, date, title, details) values (tests.assignment('student', 'parity-singapore-math'), date '2026-01-01', 'parity-plan-2', '{"session":1,"week":2,"topic":"Solve by Assuming","assignment":"Practice pp. 31-32","page_start":31,"page_end":32,"kind":"practice","reading_only":true,"pdf_offset":2}'::jsonb) returning id)
  insert into tests.world select 'parity-plan-2', id from p;
end $world$;
